/bin/zsh -lc "node - <<'NODE'
const fs=require('fs'), crypto=require('crypto');
for (const manifestPath of [
  '.planning/milestones/M003/reviews/evidence/pronunciation-design-entry-107/product-manifest.json',
  '.planning/milestones/M003/design/pronunciation/evidence/M003-UI-14-source-manifest.json'
]) {
  const m=JSON.parse(fs.readFileSync(manifestPath,'utf8'));
  const bad=[];
  for (const [p,want] of Object.entries(m.files)) {
    const got=crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
    if(got"'!==want) bad.push(p);
  }
  console.log(`${manifestPath}: ${bad.length ? '"'FAIL '+bad.join(', ') : 'PASS '+Object.keys(m.files).length+'/'+Object.keys(m.files).length}"'`);
}
const req=[
 '"'.planning/milestones/M003/design/theme.css',
 '.planning/milestones/M003/design/prototype/index.html',
 '.planning/milestones/M003/design/interactions.md',
 '.planning/milestones/M003/design/responsive-accessibility.md',
 '.planning/milestones/M003/handoffs/uiux.md'
];
console.log('CURRENT_UI_REQUIRED: '+req.every(fs.existsSync)+' '+req.filter(fs.existsSync).length+'/'+req.length);
const locked='.planning/milestones/M003/reviews/evidence/start/locked-profile.yaml';
console.log('LOCKED_PROFILE_SHA256: '+crypto.createHash('sha256').update(fs.readFileSync(locked)).digest('hex'));
NODE
rg -n 'product/to-c|product-maya' .planning/milestones/M003/reviews/evidence/start/locked-profile.yaml .planning/agt/agents.yaml
rg -n 'M003-UI-14|awaiting_user_review|not_approved|CR-313|UAT3015|4174|implementation|technical' .planning/workflow/state.yaml .planning/milestones/M003/handoffs/uiux.md .planning/milestones/M003/changes/CR-313.md .planning/agt/project.yaml"

